ck(e){const r=stick.getBoundingClientRect(),dx=e.clientX-(r.left+r.width/2),dy=e.clientY-(r.top+r.height/2),len=Math.hypot(dx,dy),max=42,k=Math.min(1,max/(len||1));state.joyX=dx*k/max;state.joyY=-dy*k/max;stick.querySelector('.stick-knob').style.transform=`translate(${dx*k}px,${dy*k}px)`}$$('[data-action]').forEach(button=>{const action=button.dataset.action;button.addEventListener('pointerdown',e=>{e.preventDefault();button.setPointerCapture(e.pointerId);if(action==='fire'||action==='aim')setAction(action,true);else setAction(action,true)});button.addEventListener('pointerup',()=>setAction(action,false));button.addEventListener('pointercancel',()=>setAction(action,false))});$$('[data-mode]').forEach(button=>button.addEventListener('click',()=>{$$('[data-mode]').forEach(b=>b.classList.toggle('selected',b===button));state.mode=button.dataset.mode}));$('#play-button').onclick=()=>startMatch(false);$('#training-button').onclick=()=>startMatch(true);$('#ready-button').onclick=()=>{$('#buy-panel').classList.add('hidden');state.paused=false;toast('LOADOUT LOCKED · GOOD HUNTING')};$('#close-buy').onclick=()=>$('#ready-button').click();$('#continue-button').onclick=()=>{if(state.roundFinished)returnToMenu();else{state.round++;state.timer=105;state.paused=false;state.player.hp=100;state.player.armor=50;state.projectiles=[];setupTeams();$('#round-overlay').classList.add('hidden');openBuy()}};$('#resume-button').onclick=()=>{state.paused=false;$('#pause-overlay').classList.add('hidden');if(!state.mobile)canvas.requestPointerLock?.()};$('#exit-button').onclick=returnToMenu;$$('[data-panel]').forEach(button=>button.addEventListener('click',()=>showPanel(button.dataset.panel)));$('.close-modal').onclick=()=>$('#panel').classList.add('hidden');$('#panel').addEventListener('click',e=>{if(e.target.id==='panel')$('#panel').classList.add('hidden')});document.addEventListener('contextmenu',e=>e.preventDefault());}
